CREATE SECRET quickref_redis (
  TYPE redis,
  host 'localhost', port '6379',
  username 'app', password 'replace-me',
  db '0', timeout_ms '2000'
);

CREATE TABLE users_snapshot AS
SELECT key, field, value
FROM redis_hscan_over_scan(
  'user:*', '*', 100, 'quickref_redis'
);
SELECT key, count(*) AS fields
FROM users_snapshot
GROUP BY key;
